	MOVD CTX_GENERALS_BASE(R19), R5
	ADD  R3, R5, R6
	ADD  R4, R5, R7
	MOVD 0(R6), R8
	MOVD 0(R7), R9
	CBZ  R8, eqg_a_invalid
	CBZ  R9, eqg_shim
	MOVD 16(R6), R3
	AND  $0x1F, R3, R4
	CMP  $20, R4
	BEQ  eqg_shim
	MOVD 16(R7), R5
	AND  $0x1F, R5, R10
	CMP  $20, R10
	BEQ  eqg_shim
	CMP  R8, R9
	BNE  eqg_store_zero
	CMP  $18, R4
	BEQ  eqg_ptr_cmp
	CMP  $22, R4
	BEQ  eqg_ptr_cmp
	CMP  $26, R4
	BNE  eqg_shim
eqg_ptr_cmp:
	MOVD 8(R6), R8
	TBZ  $7, R3, eqg_a_direct
	MOVD (R8), R8
eqg_a_direct:
	MOVD 8(R7), R9
	TBZ  $7, R5, eqg_b_direct
	MOVD (R9), R9
eqg_b_direct:
	MOVD $0, R4
	CMP  R8, R9
	BNE  eqg_store
	MOVD $1, R4
	B    eqg_store
eqg_a_invalid:
	CBNZ R9, eqg_shim
	MOVD $1, R4
	B    eqg_store
eqg_store_zero:
	MOVD $0, R4
eqg_store:
	LSR  $8, R0, R3
	AND  $0xFF, R3, R3
	MOVD R4, (R23)(R3<<3)
	DISPATCH_NEXT()
eqg_shim:
	B    ·handlerPathBShimEqualGeneral(SB)

